/work/src/styles.css.content:
:root {
  color-scheme: dark;
  font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #F4F6FF;
  background: #090B14;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-optical-sizing: auto;
  font-weight: 400;
}

* { box-sizing: border-box; }
html { min-width: 320px; background: #090B14; }
body { min-width: 320px; min-height: 100vh; margin: 0; font-size: 16px; line-height: 24px; }
button, input, select, textarea { font: inherit; }
button, select, input, textarea { color: #F4F6FF; }

:focus-visible {
  outline: 3px solid #FFFFFF;
  outline-offset: 2px;
}

.game-shell {
  display: grid;
  gap: 24px;
  width: min(100%, 1120px);
  min-width: 0;
  margin-inline: auto;
  padding: 16px;
}

.game-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding-block: 8px;
}

.eyebrow,
.win-kicker {
  margin-bottom: 4px;
  color: #B8BDD2;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.12em;
}

h1 { margin-bottom: 4px; font-size: 24px; line-height: 32px; letter-spacing: 0.05em; }
p { margin: 0; }
.intro, .game-footer, .pause-note { color: #B8BDD2; }
.game-footer { font-size: 14px; }

.header-mark { display: flex; gap: 6px; padding-right: 4px; }
.header-mark span {
  display: block;
  width: 12px;
  height: 12px;
  border: 2px solid #63E7FF;
  border-radius: 3px;
  transform: rotate(45deg);
}
.header-mark span:nth-child(2) { border-color: #FF71D6; }
.header-mark span:nth-child(3) { border-color: #8BEA7D; }

.game-panel { display: grid; gap: 16px; min-width: 0; }
.deal-controls { display: flex; align-items: end; justify-content: space-between; gap: 16px; }
.size-control { display: grid; gap: 6px; }
.size-control label, .reproduction-fields label { color: #B8BDD2; font-size: 14px; }

button, select {
  min-height: 44px;
  padding: 8px 12px;
  background: #141827;
  border: 1px solid #757C9A;
  border-radius: 6px;
}

button { cursor: pointer; font-weight: 600; }
button:hover, select:hover { border-color: #F4F6FF; }
button:active { background: #1B2034; }
button:disabled { cursor: not-allowed; }
select { min-width: 108px; }
.start-controls { display: flex; flex-wrap: wrap; gap: 8px; }

.score-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.score-strip p {
  display: flex;
  align-items: baseline;
  gap: 6px;
  padding: 8px 12px;
  color: #B8BDD2;
  background: #141827;
  border: 1px solid #757C9A;
  border-radius: 6px;
  white-space: nowrap;
}

.score-strip strong { color: #F4F6FF; font-variant-numeric: tabular-nums; }

.win-banner {
  display: grid;
  gap: 4px;
  padding: 12px 16px;
  color: #F4F6FF;
  background: #141827;
  border: 1px solid #8BEA7D;
  border-radius: 8px;
}

.win-kicker { margin: 0; color: #8BEA7D; }
.win-summary { font-size: 18px; font-weight: 700; }
.win-time { color: #B8BDD2; }
.win-banner.is-celebrating { animation: win-pulse 600ms ease-out 1; }

@keyframes win-pulse {
  0% { box-shadow: 0 0 0 0 #8BEA7D; }
  45% { box-shadow: 0 0 0 6px #8BEA7D; }
  100% { box-shadow: 0 0 0 0 #8BEA7D; }
}

.pause-note { font-size: 14px; }
.sr-announcer {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 640px) {
  .game-shell { gap: 16px; }
  .deal-controls { align-items: stretch; flex-direction: column; }
  .size-control { display: flex; align-items: center; justify-content: space-between; }
  .start-controls { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .start-controls button { min-width: 0; }
  .score-strip { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .score-strip p { justify-content: space-between; padding-inline: 8px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; }
  .win-banner.is-celebrating { animation: none; }
}

