/work/src/game/controls/GameStatus.tsx.content:
import { formatElapsed } from "../session/deal.ts";
import type { GameState } from "../types.ts";
import { isWon } from "../state.ts";
import "./game-status.css";

export type GameStatusProps = Readonly<{
  game: GameState;
  bestScore: number | null;
  celebrating: boolean;
}>;

export function GameStatus({ game, bestScore, celebrating }: GameStatusProps) {
  const complete = isWon(game);
  const pairs = game.matched.length / 2;

  return (
    <>
      <div className="score-strip">
        <p>Moves: <strong>{game.moves}</strong></p>
        <p>Pairs: <strong>{pairs}/{game.board.deck.length / 2}</strong></p>
        <p>Time: <strong>{formatElapsed(game.elapsedMs)}</strong></p>
        <p>Best: <strong>{bestScore ?? "none"}</strong></p>
      </div>
      {complete && (
        <section className={`win-banner${celebrating ? " is-celebrating" : ""}`} aria-label="Game complete">
          <p className="win-kicker">ALL PAIRS FOUND</p>
          <p className="win-summary">Completed in {game.moves} moves</p>
          <p className="win-time">Time: {formatElapsed(game.elapsedMs)}</p>
        </section>
      )}
    </>
  );
}

/work/src/game/controls/GameControls.tsx.content:
import { supportedSizes, type BoardSize } from "../types.ts";
import "./game-controls.css";

export type GameControlsProps = Readonly<{
  size: BoardSize;
  paused: boolean;
  onSizeChange(size: BoardSize): void;
  onNewGame(): void;
  onRestart(): void;
  onResume(): void;
}>;

export function GameControls({ size, paused, onSizeChange, onNewGame, onRestart, onResume }: GameControlsProps) {
  function chooseSize(value: string): void {
    const selected = supportedSizes.find((candidate) => candidate === Number(value));
    if (selected !== undefined) onSizeChange(selected);
  }

  return (
    <div className="deal-controls">
      <div className="size-control">
        <label htmlFor="grid-size">Grid size</label>
        <select id="grid-size" value={size} onChange={(event) => chooseSize(event.currentTarget.value)}>
          {supportedSizes.map((side) => <option key={side} value={side}>{side}x{side}</option>)}
        </select>
      </div>
      <div className="start-controls">
        <button type="button" onClick={onNewGame}>New Game</button>
        <button type="button" onClick={onRestart}>Restart</button>
        {paused && <button type="button" onClick={onResume}>Resume</button>}
      </div>
    </div>
  );
}

