    game,
    bestScore: preferences.bestScores[game.board.size] ?? null,
    isPaused,
    isCelebrating,
    boardRevision,
    announcement,
    loadStatus,
    activate,
    changeSize,
    newGame,
    restart,
    loadBoard,
    loadSnapshot,
    exportSnapshot,
    resume
  };
}
